    if not isinstance(error, PermissionError):
        return False
    trace = error.__traceback__
    while trace is not None:
        filename = trace.tb_frame.f_code.co_filename
        if filename.startswith("<frozen importlib."):
            return True
        trace = trace.tb_next
    return False


